#include <iostream>
#include <vector>
#include <algorithm>
struct Item{int key;int original;};
int main(){int n,target;if(!(std::cin>>n>>target)||n<0||n>32||target< -10000||target>10000){std::cout<<"invalid\n";return 0;}
 std::vector<Item>a;for(int i=0;i<n;++i){int x;if(!(std::cin>>x)||x< -10000||x>10000){std::cout<<"invalid\n";return 0;}a.push_back({x,i});}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 std::stable_sort(a.begin(),a.end(),[](const Item&a,const Item&b){return a.key<b.key;});
 auto first=std::lower_bound(a.begin(),a.end(),target,[](const Item&a,int x){return a.key<x;});
 auto last=std::upper_bound(a.begin(),a.end(),target,[](int x,const Item&a){return x<a.key;});
 for(std::size_t i=0;i<a.size();++i){if(i)std::cout<<' ';std::cout<<a[i].key<<':'<<a[i].original;}
 std::cout<<'\n'<<(first==last?-1:static_cast<long long>(first-a.begin()))<<' '<<(last-first)<<'\n';
}
